select catalog.relate(n.slug, 'side_story_of', 'detective-conan-anime')
from catalog.membership m join catalog.node n on n.id = m.member_id
where m.group_id = catalog.id('detective-conan-films');
select catalog.relate('lupin-the-3rd-vs-detective-conan-the-movie', 'crossover_with', 'detective-conan-anime');

select catalog.add_ordering('detective-conan-films', 'release', 'release order',
  'The numbered films in theatrical release order. These are original side stories, not a continuous sequel plot.') as o \gset
select catalog.add_step(:'o', substring(m.position_label from 2)::int, n.slug)
from catalog.membership m join catalog.node n on n.id = m.member_id
where m.group_id = catalog.id('detective-conan-films');

